// `denext migrate --from fresh`: Fresh's file-route conventions mapped onto denext's `app/`
// tree, and the source of the files the migration generates (`middleware.ts` and the `app/`
// pages, layouts, not-found page and route handlers that run the app's Fresh modules through
// `denext/fresh/server`).

import { dirname, relative } from "@std/path";

/** The header of every file the Fresh migration generates (re-running overwrites them). */
export const FRESH_GEN_HEADER =
  "// generated by `denext migrate` (from Fresh) — safe to edit; re-running may overwrite\n";

/** What a file under `routes/` is. */
export type FreshFileKind = "route" | "app" | "layout" | "middleware" | "notFound" | "error";

/** A file under `routes/`. */
export interface FreshFile {
  /** The path under `routes/` without the extension, `/`-separated (`blog/[slug]`). */
  id: string;
  /** The path from the project root (`routes/blog/[slug].tsx`). */
  path: string;
  /** What it is. */
  kind: FreshFileKind;
  /** Its directory under `routes/` (`blog`; `""` for the root). */
  dir: string;
  /** Its source. */
  source: string;
}

/** The kind of a routes file from its base name (without the extension). */
export function fileKind(base: string): FreshFileKind {
  switch (base) {
    case "_app":
      return "app";
    case "_layout":
      return "layout";
    case "_middleware":
      return "middleware";
    case "_404":
      return "notFound";
    case "_500":
    case "_error":
      return "error";
    default:
      return "route";
  }
}

/** Translate one path segment to its Fresh pattern piece (`[id]` → `:id`, `[[id]]` → `{/:id}?`). */
function segmentPattern(part: string): { piece: string; optional: boolean } {
  let piece = "";
  let optional = false;
  for (let j = 0; j < part.length; j++) {
    const ch = part[j];
    if (ch === "[" && part[j + 1] === "[") {
      optional = true;
      piece += "{/:";
      j++;
    } else if (ch === "[") {
      piece += ":";
    } else if (ch === "]" && part[j + 1] === "]") {
      piece += "}?";
      j++;
    } else if (ch !== "]") {
      piece += ch;
    }
  }
  return { piece, optional };
}

/**
 * Fresh's URL pattern for a route id (its `pathToPattern`): `index` is the directory, a
 * `(group)` adds nothing, `[id]` is `:id`, `[...rest]` is `:rest*`, `[[id]]` is optional.
 *
 * @param id The route id (`blog/[slug]`).
 * @returns The `URLPattern` pathname (`/blog/:slug`).
 */
export function freshPattern(id: string): string {
  const parts = id.split("/");
  if (parts[parts.length - 1] === "index") parts.pop();
  let route = "";
  let required = 0;
  for (const part of parts) {
    if (part.startsWith("[...") && part.endsWith("]")) {
      route += `/:${part.slice(4, -1)}*`;
      continue;
    }
    if (part.startsWith("(") && part.endsWith(")")) continue;
    const { piece, optional } = segmentPattern(part);
    if (optional) route += piece;
    else {
      required++;
      route += "/" + piece;
    }
  }
  if (route === "") return "/";
  if (route.startsWith("{/") && required === 0) route = route.replace("{/", "/{");
  return route;
}

/** Whether a path segment maps to a denext folder as is. */
function folderSegment(part: string): boolean {
  if (/^\(.+\)$/.test(part)) return true; // a route group
  if (/^\[(?:\.\.\.)?[A-Za-z_$][\w$]*\]$/.test(part)) return true; // [id], [...rest]
  if (/[[\]]/.test(part)) return false; // [[id]], foo-[id], [a]@[b]
  // `_x` is a private folder and `@x` a parallel slot in `app/`; `(…)` an interception.
  return part !== "" && !/^[_@(]/.test(part);
}

/**
 * The `app/` folder a routes directory or route maps to, or null when a segment has no folder
 * equivalent (an optional or partial-segment parameter, a `_` / `@` name).
 *
 * @param id A route id or directory under `routes/`.
 * @param isRoute It is a route (a trailing `index` is its directory).
 * @returns The folder's segments.
 */
export function appFolder(id: string, isRoute: boolean): string[] | null {
  const parts = id === "" ? [] : id.split("/");
  if (isRoute && parts[parts.length - 1] === "index") parts.pop();
  return parts.every(folderSegment) ? parts : null;
}

/** The URL path of an `app/` folder (groups add nothing). */
export function folderUrl(folder: string[]): string {
  const path = folder.filter((p) => !p.startsWith("(")).join("/");
  return "/" + path;
}

/**
 * Where a route the folder tree cannot express is generated: under the deepest ancestor
 * directory that maps to a folder (so its layouts still wrap it), in `fresh-route-<id>`.
 *
 * @param id The route id.
 * @returns The folder's segments.
 */
export function internalFolder(id: string): string[] {
  const parts = id.split("/").slice(0, -1);
  while (parts.length > 0 && appFolder(parts.join("/"), false) === null) parts.pop();
  const slug = id.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "index";
  return [...parts, `fresh-route-${slug}`];
}

/** Whether `dir` is `ancestor` or below it (both `/`-separated directories under `routes/`). */
export function isUnder(dir: string, ancestor: string): boolean {
  return ancestor === "" || dir === ancestor || dir.startsWith(ancestor + "/");
}

/** A relative import specifier from the file `from` to the file `to` (both absolute). */
export function importPath(from: string, to: string): string {
  const rel = relative(dirname(from), to).replaceAll("\\", "/");
  return rel.startsWith(".") ? rel : "./" + rel;
}

/** Options shared by the generated files' runtime calls (`{ id, v1 }`). */
function optionsLiteral(id: string, v1: boolean, extra: string[] = []): string {
  const parts = [`id: ${JSON.stringify(id)}`, ...(v1 ? ["v1: true"] : []), ...extra];
  return `{ ${parts.join(", ")} }`;
}

/** A generated `page.tsx`. */
export function pageSource(
  file: string,
  route: FreshFile,
  routeAbs: string,
  errorAbs: string | null,
  v1: boolean,
  internal: boolean,
): string {
  const imports = [
    `import { freshPage } from "denext/fresh/server";`,
    `import * as route from "${importPath(file, routeAbs)}";`,
    ...(errorAbs ? [`import * as error from "${importPath(file, errorAbs)}";`] : []),
  ];
  const extra = [...(errorAbs ? ["error"] : []), ...(internal ? ["internal: true"] : [])];
  return `${FRESH_GEN_HEADER}// The Fresh route routes/${route.id}: its handler runs in middleware.ts, its page here.
${imports.join("\n")}

export default freshPage(route, ${optionsLiteral(route.id, v1, extra)});
`;
}

/** A generated `layout.tsx` for a `_layout` (or the `_app` wrapper, with `app`). */
export function layoutSource(
  file: string,
  layout: FreshFile,
  abs: string,
  v1: boolean,
  app: boolean,
  cssImports: string[],
): string {
  const css = cssImports.map((c) => `import "${importPath(file, c)}";\n`).join("");
  return `${FRESH_GEN_HEADER}// The Fresh ${app ? "app wrapper" : "layout"} routes/${layout.id}.
${css}import { freshLayout } from "denext/fresh/server";
import * as layout from "${importPath(file, abs)}";

export default freshLayout(layout, ${
    optionsLiteral(app ? "_app" : layout.dir, v1, app ? ["app: true"] : [])
  });
`;
}

/** The root `layout.tsx` of an app with no `_app` (it only carries the stylesheets). */
export function bareRootLayoutSource(file: string, cssImports: string[]): string {
  const css = cssImports.map((c) => `import "${importPath(file, c)}";\n`).join("");
  return `${FRESH_GEN_HEADER}// The app has no routes/_app: denext renders the document around the pages.
${css}
export default function RootLayout({ children }: { children?: unknown }) {
  return children;
}
`;
}

/** The generated `not-found.tsx`. */
export function notFoundSource(file: string, mod: FreshFile, abs: string, v1: boolean): string {
  return `${FRESH_GEN_HEADER}// The Fresh ${
    mod.kind === "notFound" ? "not-found page" : "error page, for a 404"
  } routes/${mod.id}.
import { freshNotFound } from "denext/fresh/server";
import * as page from "${importPath(file, abs)}";

export default freshNotFound(page, ${optionsLiteral(mod.id, v1)});
`;
}

/** A generated `route.ts` for a handler-only route, exporting the methods it handles. */
export function routeHandlerSource(
  file: string,
  route: FreshFile,
  abs: string,
  v1: boolean,
  methods: string[],
): string {
  return `${FRESH_GEN_HEADER}// The Fresh route routes/${route.id} (no page component): its handler answers here.
import { freshRouteHandler } from "denext/fresh/server";
import * as route from "${importPath(file, abs)}";

const handler = freshRouteHandler(route, ${optionsLiteral(route.id, v1)});
export { ${methods.map((m) => `handler as ${m}`).join(", ")} };
`;
}

/** One route as the generated `middleware.ts` lists it. */
export interface MiddlewareRouteSpec {
  /** The route. */
  file: FreshFile;
  /** Its module's absolute path. */
  abs: string;
  /** Its URL pattern. */
  pattern: string;
  /** It has a page component. */
  page: boolean;
  /** Indices of the `_middleware` files wrapping it. */
  middlewares: number[];
  /** Ids of the `_layout` files wrapping it. */
  layouts: string[];
  /** The internal path its page is generated at (a pattern the folder tree cannot express). */
  internal?: string;
  /** A handler-only route the folder tree cannot express: the middleware answers it. */
  inMiddleware?: boolean;
}

/** What the generated `middleware.ts` imports and lists. */
export interface MiddlewareSpec {
  /** The app is a Fresh 1.x app. */
  v1: boolean;
  /** The Fresh 2 `main.ts` (absolute), when there is one. */
  main: string | null;
  /** The `_middleware` files (absolute paths) and the URL prefix each covers. */
  middlewares: { file: FreshFile; abs: string; prefix: string | null }[];
  /** The `_layout` files (absolute paths). */
  layouts: { file: FreshFile; abs: string }[];
  /** The routes, in match order. */
  routes: MiddlewareRouteSpec[];
}

/** The source of the generated root `middleware.ts`. */
export function middlewareSource(file: string, spec: MiddlewareSpec): string {
  const imports = [`import { freshMiddleware } from "denext/fresh/server";`];
  if (spec.main) imports.push(`import * as main from "${importPath(file, spec.main)}";`);
  spec.middlewares.forEach((m, i) =>
    imports.push(`import * as mw${i} from "${importPath(file, m.abs)}";`)
  );
  spec.layouts.forEach((l, i) =>
    imports.push(`import * as layout${i} from "${importPath(file, l.abs)}";`)
  );
  spec.routes.forEach((r, i) =>
    imports.push(`import * as route${i} from "${importPath(file, r.abs)}";`)
  );
  const mws = spec.middlewares.map((m, i) =>
    `    { id: ${JSON.stringify(m.file.dir)}, prefix: ${JSON.stringify(m.prefix)}, mod: mw${i} },\n`
  ).join("");
  const layouts = spec.layouts.map((l, i) =>
    `    { id: ${JSON.stringify(l.file.dir)}, mod: layout${i} },\n`
  ).join("");
  const routes = spec.routes.map((r, i) => routeLine(r, i)).join("");
  return `${FRESH_GEN_HEADER}// The Fresh app's request pipeline: main.ts's middleware and code routes, the routes/
// _middleware files, and each route's handler, run before denext renders the page.
${imports.join("\n")}

export default freshMiddleware({
${spec.v1 ? "  v1: true,\n" : ""}${spec.main ? "  main,\n" : ""}  middlewares: [
${mws}  ],
  layouts: [
${layouts}  ],
  routes: [
${routes}  ],
});

// Everything but denext's own assets runs through the Fresh middleware, as in Fresh.
export const config = { matcher: ["/((?!_denext/).*)"] };
`;
}

/** One `routes` entry of the generated `middleware.ts`. */
function routeLine(r: MiddlewareRouteSpec, i: number): string {
  const fields = [
    `id: ${JSON.stringify(r.file.id)}`,
    `pattern: ${JSON.stringify(r.pattern)}`,
    `mod: route${i}`,
    `page: ${r.page}`,
    `middlewares: [${r.middlewares.join(", ")}]`,
    `layouts: [${r.layouts.map((l) => JSON.stringify(l)).join(", ")}]`,
    ...(r.internal ? [`internal: ${JSON.stringify(r.internal)}`] : []),
    ...(r.inMiddleware ? ["inMiddleware: true"] : []),
  ];
  return `    { ${fields.join(", ")} },\n`;
}
